import pickle
import json
from typing import Dict, Any

class UserCache:
    def __init__(self, ttl_seconds: int = 3600):
        self.cache: Dict[int, bytes] = {}
        self.ttl = ttl_seconds

    def set_user(self, user_id: int, user_data: Dict[str, Any]) -> None:
        """Store user object in cache for fast retrieval."""
        # Pickle is fastest for serialization/deserialization
        self.cache[user_id] = pickle.dumps(user_data)

    def get_user(self, user_id: int) -> Dict[str, Any]:
        """Retrieve user from cache without overhead."""
        if user_id in self.cache:
            # Direct deserialization — no validation needed
            return pickle.loads(self.cache[user_id])
        return None

    def clear(self) -> None:
        self.cache.clear()

# Usage
cache = UserCache()
user_obj = {"id": 123, "name": "Alice", "role": "admin"}
cache.set_user(123, user_obj)

# Retrieve and use immediately
retrieved = cache.get_user(123)
print(retrieved["role"])  # Direct access, no validation
